namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.Add(new(NextId(), "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new(NextId(), "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new(NextId(), "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-2)));
    }

    /// <summary>Returns all notifications up to this moment.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>Simulates an incoming notification (called by a background generator).</summary>
    public void AddRandom()
    {
        string[] templates =
        [
            "Server CPU usage is at {0}%.",
            "User #{0} just signed up.",
            "Deployment #{0} completed.",
            "Disk usage alert: {0}% full.",
            "Backup #{0} finished successfully.",
        ];

        var rng = Random.Shared;
        var msg = string.Format(templates[rng.Next(templates.Length)], rng.Next(1, 100));

        lock (_lock)
        {
            _notifications.Add(new(NextId(), msg, DateTime.UtcNow));
        }
    }

    private int NextId() => _nextId++;
}

namespace NotificationsApp.Services;

/// <summary>
/// Hosted service that periodically adds fake notifications so the polling
/// loop on the page has something new to pick up.
/// </summary>
public class NotificationGeneratorService(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            notifications.AddRandom();
        }
    }
}

